function main(): void {
  const S = Symbol('s');
  const o: any = Object.defineProperties({ a: 1 }, { [S]: { value: 7, writable: true, configurable: true } });
  console.log(o[S], Object.getOwnPropertySymbols(o).length, Object.keys(o).join());
  const c: any = Object.assign({}, o);
  console.log(c[S], Object.getOwnPropertySymbols(c).length);
  const sp: any = { ...o };
  console.log(sp[S], Object.getOwnPropertySymbols(sp).length, Object.keys(o).join());
}
